package com.clara.memory.semantic.milvus;
import com.clara.kernel.*;import com.clara.memory.semantic.api.*;import java.io.IOException;import java.security.*;import java.util.*;import org.junit.Test;import static org.junit.Assert.*;
public class MilvusSemanticMemoryStoreTest {
 @Test public void batchesWritesAndUsesExactCollectionIdentity(){FakeBackend backend=new FakeBackend();MilvusSemanticMemoryStore store=new MilvusSemanticMemoryStore(config(2,10),backend);List<MemoryEntry> entries=new ArrayList<MemoryEntry>();for(int i=0;i<5;i++)entries.add(entry("id"+i,"tenant","c",new float[]{1,i},i,0,"blue"));store.upsert(entries);assertEquals(3,backend.upsertCalls);assertEquals(5,backend.entries.size());assertEquals("model",backend.expected.getEmbeddingModel());assertEquals(2,backend.expected.getDimension());}
 @Test public void pushesFiltersAndRejectsCrossTenantBackendResults(){FakeBackend backend=new FakeBackend();long now=100;backend.searchResults=Arrays.asList(entry("best","tenant","c",new float[]{1,0},1,0,"blue"),entry("leak","other","c",new float[]{1,0},2,0,"blue"),entry("tag","tenant","c",new float[]{1,0},3,0,"red"),entry("second","tenant","c",new float[]{0.8f,0.2f},4,0,"blue"));MilvusSemanticMemoryStore store=new MilvusSemanticMemoryStore(config(10,10),backend);SemanticMemoryQuery query=new SemanticMemoryQuery("tenant","user","c","general",new float[]{1,0},2,0.5,now,Collections.singletonMap("tag","blue"));List<MemoryMatch> found=store.search(query);assertEquals(2,found.size());assertEquals("best",found.get(0).getEntry().getId());assertEquals("second",found.get(1).getEntry().getId());assertEquals("tenant",backend.query.getQuery().getTenantId());assertEquals(4,backend.query.getCandidateLimit());}
 @Test public void deletesWithTenantAndMapsRetryableBackendFailure(){FakeBackend backend=new FakeBackend();MilvusSemanticMemoryStore store=new MilvusSemanticMemoryStore(config(10,10),backend);store.deleteByConversation("tenant","conversation");assertEquals("tenant",backend.deletedTenant);assertEquals("conversation",backend.deletedConversation);backend.failure=new MilvusBackendException("down",true,null);try{store.search(new SemanticMemoryQuery("tenant",null,null,null,new float[]{1,0},1,-1,1,null));fail("expected backend failure");}catch(ClaraException e){assertEquals(ErrorCodes.SEMANTIC_MEMORY_BACKEND_FAILED,e.getError().getCode());assertTrue(e.getError().isRetryable());}}
 @Test public void rejectsCollectionAndRequestDimensionMismatch(){FakeBackend wrong=new FakeBackend();wrong.returned=new MilvusCollectionSpec("memory","other","v1",2,"COSINE");assertCode(ErrorCodes.SEMANTIC_MEMORY_CONFIG_MISMATCH,new Runnable(){public void run(){new MilvusSemanticMemoryStore(config(10,10),wrong);}});MilvusSemanticMemoryStore store=new MilvusSemanticMemoryStore(config(10,1),new FakeBackend());assertCode(ErrorCodes.SEMANTIC_MEMORY_RESOURCE_LIMIT,new Runnable(){public void run(){store.search(new SemanticMemoryQuery("tenant",null,null,null,new float[]{1,0},2,-1,1,null));}});assertCode(ErrorCodes.SEMANTIC_MEMORY_CONFIG_MISMATCH,new Runnable(){public void run(){store.upsert(Collections.singletonList(entry("bad","tenant","c",new float[]{1,0,0},1,0,"blue")));}});}
 @Test public void rejectsUnsafeCollectionSchemaAndClosesBackend(){FakeBackend wrong=new FakeBackend();Set<String> fields=new LinkedHashSet<String>(new MilvusCollectionSpec("memory","model","v1",2,"COSINE").getRequiredFields());fields.remove("tenant_id");wrong.returned=new MilvusCollectionSpec("memory","model","v1",2,"COSINE",fields);assertCode(ErrorCodes.SEMANTIC_MEMORY_CONFIG_MISMATCH,new Runnable(){public void run(){new MilvusSemanticMemoryStore(config(10,10),wrong);}});assertTrue(wrong.closed);}
 @Test public void rejectsBackendResultsBeyondRequestedCandidateLimit(){FakeBackend backend=new FakeBackend();backend.searchResults=Arrays.asList(entry("one","tenant","c",new float[]{1,0},1,0,"blue"),entry("two","tenant","c",new float[]{1,0},2,0,"blue"),entry("three","tenant","c",new float[]{1,0},3,0,"blue"));MilvusSemanticMemoryStore store=new MilvusSemanticMemoryStore(config(10,10),backend);assertCode(ErrorCodes.SEMANTIC_MEMORY_RESOURCE_LIMIT,new Runnable(){public void run(){store.search(new SemanticMemoryQuery("tenant",null,null,null,new float[]{1,0},1,-1,1,null));}});}
 @Test public void closesBackendWhenCollectionInitializationFails(){FakeBackend backend=new FakeBackend();backend.failure=new MilvusBackendException("down",true,null);assertCode(ErrorCodes.SEMANTIC_MEMORY_BACKEND_FAILED,new Runnable(){public void run(){new MilvusSemanticMemoryStore(config(10,10),backend);}});assertTrue(backend.closed);}
 private static MilvusSemanticMemoryConfig config(int batch,int topK){return new MilvusSemanticMemoryConfig("memory","model","v1",2,batch,topK,2);}private static MemoryEntry entry(String id,String tenant,String conversation,float[] vector,long created,long expires,String tag){return new MemoryEntry(id,tenant,"user",conversation,"general",MemorySourceType.CONVERSATION,conversation,id,sha(id),vector,created,expires,Collections.singletonMap("tag",tag));}private static String sha(String value){try{byte[] bytes=MessageDigest.getInstance("SHA-256").digest(value.getBytes(java.nio.charset.StandardCharsets.UTF_8));StringBuilder out=new StringBuilder();for(byte b:bytes)out.append(String.format("%02x",b&255));return out.toString();}catch(Exception e){throw new IllegalStateException(e);}}private static void assertCode(String code,Runnable action){try{action.run();fail("expected "+code);}catch(ClaraException e){assertEquals(code,e.getError().getCode());}}
 private static final class FakeBackend implements MilvusBackend {private MilvusCollectionSpec expected,returned;private final List<MemoryEntry> entries=new ArrayList<MemoryEntry>();private List<MemoryEntry> searchResults=Collections.emptyList();private MilvusBackendQuery query;private int upsertCalls;private String deletedTenant,deletedConversation;private MilvusBackendException failure;private boolean closed;public MilvusCollectionSpec ensureCollection(MilvusCollectionSpec expected){this.expected=expected;failIfNeeded();return returned==null?expected:returned;}public void upsert(String collection,List<MemoryEntry> values){failIfNeeded();upsertCalls++;entries.addAll(values);}public List<MemoryEntry> search(String collection,MilvusBackendQuery query){failIfNeeded();this.query=query;return searchResults;}public void deleteByConversation(String collection,String tenant,String conversation){failIfNeeded();deletedTenant=tenant;deletedConversation=conversation;}public void close()throws IOException{closed=true;}private void failIfNeeded(){if(failure!=null)throw failure;}}
}
